// Contrôles propres au lot fictif quartier-01. Aucun appel réseau.
const sources = {
  "M001": {
    "source": "entrees/courriels/01-nora.txt",
    "texte": "Jeu de données fictif — Les ateliers du quartier\nMessage-ID: <M001@atelier.example>\nDate: 2026-09-15T09:10:00+02:00\nDe: Nora <nora@example.org>\nÀ: Équipe des ateliers <equipe@example.org>\nObjet: Deux places en Reliure\n\nBonjour,\n\nNous aimerions participer à l’atelier Reliure. Pouvez-vous noter\nune demande pour deux personnes ? Nous attendrons votre confirmation.\n\nMerci,\nNora\n"
  },
  "M002": {
    "source": "entrees/courriels/02-leo.txt",
    "texte": "Jeu de données fictif — Les ateliers du quartier\nMessage-ID: <M002@atelier.example>\nDate: 2026-09-15T10:05:00+02:00\nDe: Léo <leo@example.org>\nÀ: Équipe des ateliers <equipe@example.org>\nObjet: Inscription à la journée\n\nBonjour,\n\nJe voudrais m’inscrire avec un ami : une place pour lui et une pour moi.\nPouvez-vous prendre notre demande en compte ?\n\nBonne journée,\nLéo\n"
  },
  "M004": {
    "source": "entrees/courriels/04-samir.txt",
    "texte": "Jeu de données fictif — Les ateliers du quartier\nMessage-ID: <M004@atelier.example>\nDate: 2026-09-10T17:20:00+02:00\nDe: Samir <samir@example.org>\nÀ: Équipe des ateliers <equipe@example.org>\nObjet: Une place en Reliure\n\nBonjour,\n\nJe souhaite participer à l’atelier Reliure, pour une personne.\nPouvez-vous enregistrer ma demande ?\n\nMerci,\nSamir\n"
  },
  "M005": {
    "source": "entrees/courriels/05-question-nora.txt",
    "texte": "Jeu de données fictif — Les ateliers du quartier\nMessage-ID: <M005@atelier.example>\nDate: 2026-09-15T11:40:00+02:00\nDe: Nora <nora@example.org>\nÀ: Équipe des ateliers <equipe@example.org>\nObjet: Horaire de Cartographie\n\nBonjour,\n\nÀ quelle heure commence l’atelier Cartographie ? Je pose la question\npour savoir si je pourrai passer le voir ; ma demande d’inscription\nporte toujours sur les deux places en Reliure.\n\nMerci,\nNora\n"
  }
};
function refuser(message) {
  throw new Error("Lot refusé : " + message);
}
function objet(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}
function clefs(value, attendues, nom) {
  if (!objet(value)) refuser(nom + " doit être un objet.");
  const presentes = Object.keys(value).sort();
  if (JSON.stringify(presentes) !== JSON.stringify([...attendues].sort())) {
    refuser(nom + " : champs absents ou inconnus.");
  }
}
const items = $input.all();
if (items.length !== 1) refuser("un seul objet d’extraction est attendu.");
const extraction = items[0].json;
clefs(extraction, ["version", "lot", "origine", "messages", "date_evenement", "horaire_cartographie", "alertes"], "extraction");
if (extraction.version !== 1 || extraction.lot !== "quartier-01") refuser("version ou lot inconnu.");
if (!["exemple_fictif", "manuel", "assistant"].includes(extraction.origine)) refuser("origine inconnue.");
if (extraction.date_evenement !== null || extraction.horaire_cartographie !== null) {
  refuser("la date et l’horaire restent à arbitrer : garder null dans ce lot.");
}
if (!Array.isArray(extraction.alertes) || extraction.alertes.length > 20 ||
    extraction.alertes.some(texte => typeof texte !== "string" || !texte.trim() || texte.length > 1000)) {
  refuser("alertes doit être une liste de textes non vides (20 textes de 1000 caractères au plus).");
}
if (!Array.isArray(extraction.messages) || extraction.messages.length !== 4) {
  refuser("les quatre messages distincts M001, M002, M004 et M005 sont attendus.");
}
const vus = new Set();
for (const message of extraction.messages) {
  clefs(message, ["id", "type", "atelier", "places", "source", "extrait"], "message");
  if (typeof message.id !== "string" || !Object.hasOwn(sources, message.id)) refuser("identifiant inconnu.");
  if (vus.has(message.id)) refuser("identifiant répété : " + message.id);
  vus.add(message.id);
  if (!["inscription", "question"].includes(message.type)) refuser(message.id + " : type inconnu.");
  if (![null, "Reliure", "Cartographie"].includes(message.atelier)) refuser(message.id + " : atelier inconnu.");
  if (message.places !== null && (!Number.isSafeInteger(message.places) || message.places <= 0)) {
    refuser(message.id + " : places doit être un entier positif ou null.");
  }
  if (message.type === "question" && message.places !== null) refuser("une question n’ajoute aucune place.");
  if (message.id === "M005" && message.type !== "question") refuser("M005 reste une question.");
  if (message.source !== sources[message.id].source) refuser(message.id + " : source incorrecte.");
  if (typeof message.extrait !== "string" || !message.extrait.trim() ||
      !sources[message.id].texte.includes(message.extrait)) {
    refuser(message.id + " : extrait absent du message source.");
  }
}
return [{
  json: {
    extraction,
    deja_connus: ["M004"],
    nouveaux: extraction.messages.filter(message => message.id !== "M004"),
    copie: {
      id: "M001",
      source: "entrees/courriels/01-nora.txt",
      doublon: "entrees/courriels/03-copie-nora.txt"
    },
    controle: "Format, identifiants et citations vérifiés ; sens des champs à relire."
  }
}];

// Cette sortie reste interne. Aucun envoi, aucune inscription confirmée,
// aucun état durable : chaque exécution repart du suivi initial.
const donnees = $input.all()[0].json;
const extraction = donnees.extraction;
function texte(value) {
  if (value === null) return "non précisé";
  return String(value).replace(/[\\`*_[\]<>|]/g, "\\$&").replace(/\r?\n/g, " ");
}
const lignes = [
  "# Les ateliers du quartier — point proposé",
  "",
  "Proposition interne non approuvée. Origine : " + texte(extraction.origine) + ".",
  "Vérifier les faits dans les sources avant de retenir ce point.",
  "",
  "## Messages nouveaux",
  "",
  "| Message | Type | Atelier | Places demandées | Source |",
  "| --- | --- | --- | --- | --- |"
];
for (const message of donnees.nouveaux) {
  lignes.push("| " + [message.id, message.type, message.atelier, message.type === "question" ? "sans objet" : message.places, message.source].map(texte).join(" | ") + " |");
}
lignes.push("", "## Extraits à relire", "");
for (const message of donnees.nouveaux) {
  lignes.push("- " + message.id + " : « " + texte(message.extrait) + " »");
}
lignes.push(
  "", "## Suivi connu et décisions manquantes", "",
  "- M004 figure déjà dans le suivi initial ; il ne crée aucune nouvelle demande.",
  "- M001 a aussi une copie : entrees/courriels/03-copie-nora.txt. Elle ne crée aucune demande supplémentaire.",
  "- Date à clarifier : 10 octobre dans CR01, 17 octobre sur le projet d’affiche de CR02.",
  "- Horaire de Cartographie à demander à l’équipe ; aucune annonce préparée.",
  "- Les demandes relevées ne confirment aucune place.",
  "", "## Alertes extraites, à vérifier", ""
);
for (const alerte of extraction.alertes) lignes.push("- " + texte(alerte));
return [{
  json: {
    statut: "proposition_interne_non_approuvee",
    lot: extraction.lot,
    origine: extraction.origine,
    nouveaux: donnees.nouveaux.map(message => message.id),
    deja_connus: donnees.deja_connus,
    controle: donnees.controle,
    point_interne: lignes.join("\n"),
    action_exterieure: false,
    persistance: false
  }
}];
